# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Build the country layer: entities, indicators, topology links and one profile per entity.

    uv run scripts/build.py          rebuild every derived file from the pins in .cache/
    uv run scripts/build.py check    rebuild in memory; fail if any committed file differs

Inputs are only (a) pinned bytes listed in MANIFEST.tsv (each re-hashed before
use; a mismatch stops the build), (b) the sibling topology tables, read by
explicit country code only, and (c) the two Leaving America tables
(leaving-america.tsv, computed by scripts/leaving_america.py; question-set.tsv,
a proposal). Nothing is fetched here: `scripts/pin.py pin` does that, through
the gate.

Outputs (all sorted, no clock, byte-identical on rerun):
  countries.tsv          one row per entity (CLDR 47 territories + Natural Earth
                         features that carry no ISO code)
  indicators.tsv         long table: key, indicator, value, year, source, manifest_id
  indicator-coverage.tsv per indicator: definition, source, licence, countries with a value / total
  links.tsv              per entity: counts of rows in other topology tables, by explicit code
  question-coverage.tsv  per question: proposed indicators and how many entities have them
  profiles/<key>.md      one short page per entity
  profiles/index.tsv     key, name, profile path, filled-indicator count

Missing values stay missing ("missing" on a page, empty in a table); nothing
is imputed, carried across, or averaged.
"""
from __future__ import annotations

import csv
import hashlib
import html
import io
import json
import re
import sys
import zipfile
from pathlib import Path

HERE = Path(__file__).resolve().parent.parent
TOPO = HERE.parent
CACHE = HERE / ".cache"
WITNESS_LLM = "llm:claude-opus-5-5 prompt=unrecorded"

# ---------------------------------------------------------------- tsv


def read_tsv(path: Path) -> list[dict[str, str]]:
    if not path.exists():
        return []
    lines = path.read_text(encoding="utf-8").splitlines()
    head = lines[0].split("\t")
    return [dict(zip(head, ln.split("\t"))) for ln in lines[1:] if ln.strip()]


def tsv_bytes(cols: list[str], rows: list[dict[str, str]]) -> bytes:
    out = ["\t".join(cols)] + ["\t".join(str(r.get(c, "")) for c in cols) for r in rows]
    return ("\n".join(out) + "\n").encode("utf-8")


# ---------------------------------------------------------------- pins

MANIFEST = {r["id"]: r for r in read_tsv(HERE / "MANIFEST.tsv")}


def pinned(pin_id: str) -> bytes:
    row = MANIFEST[pin_id]
    hits = [p for p in CACHE.glob(pin_id + ".*") if p.stem == pin_id]
    if len(hits) != 1:
        sys.exit(f"pin {pin_id}: cache file missing (run: uv run scripts/pin.py pin --only {pin_id})")
    data = hits[0].read_bytes()
    if hashlib.sha256(data).hexdigest() != row["sha256"] or str(len(data)) != row["bytes"]:
        sys.exit(f"pin {pin_id}: HASH MISMATCH against MANIFEST.tsv")
    return data


# ---------------------------------------------------------------- entities

def cldr() -> tuple[dict[str, dict[str, str]], dict[str, str], dict[str, str], set[str]]:
    sup = pinned("cldr-supplemental").decode("utf-8")
    en = pinned("cldr-en").decode("utf-8")
    codes = {}
    for code, attrs in re.findall(r'<territoryCodes type="([A-Z0-9]{2,3})"([^>]*)/>', sup):
        a = dict(re.findall(r'(\w+)="([^"]*)"', attrs))
        codes[code] = {"numeric": a.get("numeric", ""), "alpha3": a.get("alpha3", "")}
    parent: dict[str, str] = {}
    un: set[str] = set()
    groups = set()
    for m in re.finditer(r'<group type="([A-Z0-9]{2,3})" contains="([^"]+)"([^>]*)/>', sup):
        gtype, contains, rest = m.groups()
        if gtype == "UN":
            un = set(contains.split())
        if "status=" in rest or 'grouping="true"' in rest:
            continue
        groups.add(gtype)
        for c in contains.split():
            parent[c] = gtype
    terr = re.search(r"<territories>(.*?)</territories>", en, re.S).group(1)  # type: ignore[union-attr]
    names = {k: html.unescape(v) for k, v in re.findall(r'<territory type="([A-Z0-9]{2,3})">([^<]+)</territory>', terr)}
    leaves = {c for c in parent if re.fullmatch(r"[A-Z]{2}", c) and c not in groups}
    out = {}
    for c in sorted(leaves):
        chain = [c]
        while chain[-1] in parent and parent[chain[-1]] != "001":
            chain.append(parent[chain[-1]])
        region, sub = chain[-1], parent[c]
        num = codes.get(c, {}).get("numeric", "")
        basis = ("iso-3166-1" if num and int(num) < 900 else
                 "user-assigned (CLDR, ISO 3166 user-assigned range)" if num else
                 "CLDR region code (no ISO numeric)")
        out[c] = {"key": c, "iso2": c, "iso3": codes.get(c, {}).get("alpha3", ""), "numeric": num,
                  "name_en": names.get(c, ""), "region_m49": region, "region": names.get(region, ""),
                  "subregion_m49": sub, "subregion": names.get(sub, ""), "code_basis": basis,
                  "un_member": "yes" if c in un else "no"}
    return out, names, parent, un


def natural_earth() -> list[dict[str, str]]:
    d = json.loads(pinned("ne-admin0-50m"))
    return [{k: str(f["properties"].get(k, "")) for k in
             ("ISO_A2_EH", "ISO_A3_EH", "ADM0_A3", "TYPE", "ADMIN", "NAME_EN")} for f in d["features"]]


ENTITY_COLS = ["key", "iso2", "iso3", "numeric", "name_en", "region", "region_m49", "subregion",
               "subregion_m49", "code_basis", "un_member", "status", "ne_adm0_a3", "ne_name",
               "ne_other_features", "sources"]


def entities() -> list[dict[str, str]]:
    ents, _, _, _ = cldr()
    ne = natural_earth()
    by2: dict[str, list[dict[str, str]]] = {}
    extra = []
    for f in ne:
        if f["ISO_A2_EH"] == "-99":
            extra.append(f)
        else:
            by2.setdefault(f["ISO_A2_EH"], []).append(f)
    for c, e in ents.items():
        feats = sorted(by2.get(c, []), key=lambda f: f["ADM0_A3"])
        prim = [f for f in feats if f["ISO_A3_EH"] == f["ADM0_A3"]] or feats[:1]
        if prim:
            p = prim[0]
            e.update(status=p["TYPE"], ne_adm0_a3=p["ADM0_A3"], ne_name=p["ADMIN"],
                     ne_other_features=" ".join(f"{f['ADM0_A3']}:{f['ADMIN']}" for f in feats if f is not p),
                     sources="cldr-47 natural-earth-50m")
        else:
            e.update(status="not in Natural Earth 1:50m", sources="cldr-47")
    for f in extra:
        k = "ne-" + f["ADM0_A3"].lower()
        ents[k] = {"key": k, "name_en": f["NAME_EN"], "code_basis": "Natural Earth ADM0_A3 only (no ISO code)",
                   "un_member": "no", "status": f["TYPE"], "ne_adm0_a3": f["ADM0_A3"], "ne_name": f["ADMIN"],
                   "sources": "natural-earth-50m"}
    unmatched = sorted(set(by2) - set(ents))
    if unmatched:
        sys.exit(f"Natural Earth codes with no CLDR territory: {unmatched}")
    return [ents[k] for k in sorted(ents)]


# ---------------------------------------------------------------- indicators

IND_DEFS = [
    # id, label, unit, source_id, pin, licence
    ("population", "Population, total (WDI SP.POP.TOTL)", "people", "world-bank-wdi", "wdi-pop", "CC BY 4.0"),
    ("gdp_pc_ppp", "GDP per capita, PPP (WDI NY.GDP.PCAP.PP.KD)", "constant 2021 international $",
     "world-bank-wdi", "wdi-gdppc-ppp", "CC BY 4.0"),
    ("electricity_access", "Access to electricity (WDI EG.ELC.ACCS.ZS)", "% of population", "world-bank-wdi",
     "wdi-elec-access", "CC BY 4.0"),
    ("inflation_cpi", "Inflation, consumer prices (WDI FP.CPI.TOTL.ZG)", "annual %", "world-bank-wdi",
     "wdi-inflation", "CC BY 4.0"),
    ("pm25", "PM2.5 mean annual exposure (WDI EN.ATM.PM25.MC.M3)", "micrograms per cubic metre",
     "world-bank-wdi", "wdi-pm25", "CC BY 4.0"),
    ("hdi", "Human Development Index (HDR 2025 time series)", "index 0-1", "undp-hdr", "hdr-composite",
     "CC BY 3.0 IGO"),
    ("mpi", "Global Multidimensional Poverty Index 2026, Table 1 (year = survey)", "index 0-1", "undp-hdr",
     "hdr-mpi", "CC BY 3.0 IGO"),
    ("grid_carbon_intensity", "Lifecycle carbon intensity of electricity (Ember, via OWID)",
     "gCO2e per kWh", "ember-via-owid", "owid-carbon-intensity", "CC BY 4.0 (Ember); OWID processing CC BY"),
    ("renewables_share_elec", "Renewables share of electricity (Ember, via OWID)", "% of generation",
     "ember-via-owid", "owid-renewables-share", "CC BY 4.0 (Ember); OWID processing CC BY"),
    ("vdem_electoral_democracy", "Electoral democracy index (V-Dem v2x_polyarchy, via OWID)", "index 0-1",
     "ember-via-owid", "owid-vdem-edi", "CC BY-SA 4.0 (V-Dem); OWID processing CC BY"),
]


def fmt(v: float) -> str:
    s = f"{v:.4g}" if abs(v) < 1e6 else f"{v:.0f}"
    return s


def latest(series: dict[str, dict[str, float]]) -> dict[str, tuple[str, float]]:
    return {k: max(ys.items()) for k, ys in series.items() if ys}


def wdi(pin: str, iso2s: set[str]) -> dict[str, tuple[str, float]]:
    # Join on the WDI record's own 2-letter country id (explicit in the source; it
    # gives Kosovo as XK while its ISO3-like code is XKX). Aggregates drop out
    # because their ids are not entity keys.
    d = json.loads(pinned(pin))
    s: dict[str, dict[str, float]] = {}
    for r in d[1] or []:
        cid = r["country"]["id"]
        if r["value"] is not None and cid in iso2s:
            s.setdefault(cid, {})[r["date"]] = float(r["value"])
    return latest(s)


def hdr(iso3: dict[str, str]) -> tuple[dict[str, tuple[str, float]], dict[str, str]]:
    rows = list(csv.DictReader(io.StringIO(pinned("hdr-composite").decode("utf-8-sig"))))
    s: dict[str, dict[str, float]] = {}
    names = {}
    for r in rows:
        k = iso3.get(r["iso3"])
        if not k:
            continue
        names[r["country"]] = k
        for col, v in r.items():
            m = re.fullmatch(r"hdi_(\d{4})", col or "")
            if m and v not in ("", None):
                s.setdefault(k, {})[m.group(1)] = float(v)
    return latest(s), names


def xlsx_rows(data: bytes, sheet: int = 1) -> list[dict[str, str]]:
    z = zipfile.ZipFile(io.BytesIO(data))
    ss = [html.unescape(re.sub(r"<[^>]+>", "", s))
          for s in re.findall(r"<si>(.*?)</si>", z.read("xl/sharedStrings.xml").decode("utf-8"), re.S)]
    out = []
    for row in re.findall(r"<row [^>]*>(.*?)</row>", z.read(f"xl/worksheets/sheet{sheet}.xml").decode("utf-8"), re.S):
        cells = {}
        for col, attrs, v in re.findall(r'<c r="([A-Z]+)\d+"([^>]*?)(?:/>|>(?:<f>.*?</f>)?(?:<v>(.*?)</v>)?.*?</c>)', row, re.S):
            cells[col] = ss[int(v)] if 't="s"' in attrs and v else v
        out.append(cells)
    return out


def mpi(name_to_key: dict[str, str]) -> tuple[dict[str, tuple[str, float]], list[str]]:
    # Table 1 is keyed by country name only. Join by exact equality with the
    # name UNDP itself pairs with an ISO3 code in the HDR time series, then with
    # the CLDR English name; anything else is reported as unjoined.
    out, unjoined = {}, []
    for r in xlsx_rows(pinned("hdr-mpi"), 1):
        name, survey, val = r.get("A", ""), r.get("B", ""), r.get("D", "")
        if not name or not re.fullmatch(r"[0-9.Ee-]+", val or "") or not re.match(r"\d{4}", survey):
            continue
        k = name_to_key.get(name)
        if k is None:
            unjoined.append(name)
            continue
        out[k] = (survey, float(val))
    return out, sorted(set(unjoined))


def owid(pin: str, iso3: dict[str, str]) -> dict[str, tuple[str, float]]:
    rows = list(csv.reader(io.StringIO(pinned(pin).decode("utf-8"))))
    s: dict[str, dict[str, float]] = {}
    for r in rows[1:]:
        k = iso3.get(r[1])
        if k and r[3] != "":
            s.setdefault(k, {})[r[2]] = float(r[3])
    return latest(s)


def indicators(ents: list[dict[str, str]]) -> tuple[list[dict[str, str]], list[dict[str, str]], dict]:
    iso2s = {e["iso2"] for e in ents if e.get("iso2")}
    iso3 = {e["iso3"]: e["key"] for e in ents if e.get("iso3")}
    vals: dict[str, dict[str, tuple[str, float]]] = {}
    for i, *_ in IND_DEFS:
        pass
    for iid, _, _, src, pin, _ in IND_DEFS:
        if src == "world-bank-wdi":
            vals[iid] = wdi(pin, iso2s)
        elif src == "ember-via-owid":
            vals[iid] = owid(pin, iso3)
    vals["hdi"], hdr_names = hdr(iso3)
    names = {e["name_en"]: e["key"] for e in ents if e.get("name_en")}
    names.update(hdr_names)
    vals["mpi"], mpi_unjoined = mpi(names)
    rows, cov = [], []
    total = len(ents)
    for iid, label, unit, src, pin, lic in IND_DEFS:
        for k in sorted(vals[iid]):
            y, v = vals[iid][k]
            rows.append({"key": k, "indicator": iid, "value": fmt(v), "year": y, "source": src, "manifest_id": pin})
        years = sorted({y for y, _ in vals[iid].values()})
        cov.append({"indicator": iid, "label": label, "unit": unit, "source": src, "manifest_id": pin,
                    "licence": lic, "with_value": str(len(vals[iid])), "total": str(total),
                    "coverage": f"{len(vals[iid])}/{total}",
                    "years": f"{years[0]}..{years[-1]}" if years else "",
                    "note": (f"latest non-empty year per entity; unjoined Table 1 names: {'; '.join(mpi_unjoined)}"
                             if iid == "mpi" else "latest non-empty year per entity")})
    rows.sort(key=lambda r: (r["key"], r["indicator"]))
    return rows, cov, vals


# ---------------------------------------------------------------- links

LINK_COLS = ["key", "bodies", "ai_centers_works", "ai_centers_institutions", "benefit_claims",
             "benefit_claim_actors", "asset_owners", "training_methods_uses", "training_methods_developers",
             "norway_bodies"]


def links(ents: list[dict[str, str]]) -> tuple[list[dict[str, str]], dict[str, str]]:
    keys = {e["iso2"] for e in ents if e.get("iso2")}
    cnt: dict[str, dict[str, int]] = {k: {} for k in keys}
    notes = {}

    def add(code: str, col: str, n: int = 1) -> None:
        if code in keys:
            cnt[code][col] = cnt[code].get(col, 0) + n

    for r in read_tsv(TOPO / "bodies.tsv"):
        add(r.get("jurisdiction", ""), "bodies")
    for r in read_tsv(TOPO / "ai-centers/computed/countries.tsv"):
        add(r.get("iso2", ""), "ai_centers_works", int(r["works"]) if r.get("works", "").isdigit() else 0)
    inst: dict[str, set[str]] = {}
    for r in read_tsv(TOPO / "ai-centers/computed/institutions.tsv"):
        inst.setdefault(r.get("country", ""), set()).add(r.get("openalex_id", ""))
    for c, ids in inst.items():
        add(c, "ai_centers_institutions", len(ids))
    actors = {r["id"]: r.get("jurisdiction", "") for r in read_tsv(TOPO / "ai-benefit-claims/actors.tsv")}
    for r in read_tsv(TOPO / "ai-benefit-claims/claims.tsv"):
        add(actors.get(r.get("actor_id", ""), ""), "benefit_claims")
    for j in actors.values():
        add(j, "benefit_claim_actors")
    owners = TOPO / "asset-owners/owners.tsv"
    if owners.exists():
        rows = read_tsv(owners)
        col = next((c for c in ("jurisdiction", "country", "iso2", "country_iso2") if rows and c in rows[0]), None)
        if col:
            for r in rows:
                add(r.get(col, ""), "asset_owners")
            notes["asset_owners"] = f"asset-owners/owners.tsv column {col}"
        else:
            notes["asset_owners"] = "asset-owners/owners.tsv present but has no explicit country-code column"
    else:
        notes["asset_owners"] = "asset-owners/owners.tsv absent at build time"
    devs: dict[str, set[str]] = {}
    for r in read_tsv(TOPO / "training-methods/uses.tsv"):
        add(r.get("country", ""), "training_methods_uses")
        devs.setdefault(r.get("country", ""), set()).add(r.get("developer", ""))
    for c, d in devs.items():
        add(c, "training_methods_developers", len(d))
    for r in read_tsv(TOPO / "norway/bodies-rows.tsv"):
        add(r.get("jurisdiction", ""), "norway_bodies")
    rows = []
    for e in ents:
        c = cnt.get(e.get("iso2", ""), {})
        rows.append({"key": e["key"], **{col: str(c.get(col, 0)) for col in LINK_COLS[1:]}})
    return rows, notes


# ---------------------------------------------------------------- questions

def question_coverage(vals: dict, total: int) -> tuple[list[dict[str, str]], list[dict[str, str]]]:
    qs = read_tsv(HERE / "question-set.tsv")
    out = []
    for q in qs:
        ids = [] if q["answered_by"] == "no-open-source" else q["answered_by"].split()
        unknown = [i for i in ids if i not in vals]
        if unknown:
            sys.exit(f"question {q['id']}: unknown indicator {unknown}")
        n = len(set.union(*[set(vals[i]) for i in ids])) if ids else 0
        out.append({"id": q["id"], "question": q["question"], "answered_by": q["answered_by"],
                    "answer_kind": q["answer_kind"], "entities_with_any": str(n), "total": str(total)})
    return out, qs


# ---------------------------------------------------------------- profiles

def profile(e: dict[str, str], vals: dict, link: dict[str, str], la: list[dict[str, str]],
            qs: list[dict[str, str]], link_notes: dict[str, str]) -> str:
    L = [f"# {e['name_en'] or e.get('ne_name', '') or e['key']}", ""]
    L += ["Generated by `scripts/build.py` from pinned sources. A profile is a set of facts with their "
          "sources, not a recommendation; national figures hide differences within the country.", ""]
    L += ["## Key", "",
          f"- key: `{e['key']}`",
          f"- ISO 3166-1 alpha-2 / alpha-3 / numeric: {e.get('iso2') or 'missing'} / {e.get('iso3') or 'missing'} / {e.get('numeric') or 'missing'}",
          f"- code basis: {e.get('code_basis', '')}",
          f"- region (CLDR containment, UN M49 codes): {e.get('region') or 'missing'} > {e.get('subregion') or 'missing'}",
          f"- UN member state (CLDR grouping): {e.get('un_member', '')}",
          f"- Natural Earth 1:50m type: {e.get('status') or 'missing'}"
          + (f" (feature `{e['ne_adm0_a3']}`, {e['ne_name']})" if e.get("ne_adm0_a3") else ""), ""]
    if e.get("ne_other_features"):
        L[-1:-1] = [f"- other Natural Earth features with this code: {e['ne_other_features']}"]
    L += ["## Indicators", "", "| indicator | value | year | source |", "|---|---|---|---|"]
    for iid, label, unit, src, pin, lic in IND_DEFS:
        v = vals[iid].get(e["key"])
        L.append(f"| {label} ({unit}) | {fmt(v[1]) if v else 'missing'} | {v[0] if v else ''} | {src} `{pin}` |")
    L += ["", "## Linked topologies (rows carrying this explicit country code)", ""]
    labels = {"bodies": "bodies.tsv bodies (jurisdiction)",
              "ai_centers_works": "AI-centers works (OpenAlex sample)",
              "ai_centers_institutions": "AI-centers institutions",
              "benefit_claims": "AI benefit claims by actor jurisdiction",
              "benefit_claim_actors": "AI benefit-claim actors",
              "asset_owners": "asset owners",
              "training_methods_uses": "training-method uses by developer country",
              "training_methods_developers": "training-method developers",
              "norway_bodies": "Norway folder bodies"}
    for col in LINK_COLS[1:]:
        note = f" ({link_notes[col]})" if col in link_notes else ""
        L.append(f"- {labels[col]}: {link[col]}{note}")
    L += ["", "## Leaving America", ""]
    if la:
        for r in la:
            L += [f"- guide page: `{r['path']}` (blob `{r['blob_sha'][:12]}`, reviewed {r['last_reviewed'] or 'missing'})",
                  f"- currency: {r['currency'] or 'missing'}; totalization agreement with the US: "
                  f"{r['totalization_agreement'] or 'missing'}; SSA benefits portable: {r['ssa_benefits_portable'] or 'missing'}",
                  f"- visa types listed: {r['visa_types'] or 'missing'}"]
    else:
        L.append("- not a Leaving America destination")
    L += ["", "## Question set", "",
          "Questions generalised from the Leaving America guide (`question-set.tsv`, a proposal). "
          "`yes` means a value is present here for an indicator proposed to bear on it; it is not an answer.", ""]
    for q in qs:
        ids = [] if q["answered_by"] == "no-open-source" else q["answered_by"].split()
        have = [i for i in ids if e["key"] in vals[i]]
        state = ("no open source" if not ids else
                 f"yes ({q['answer_kind']}: {' '.join(have)})" if have else f"missing ({' '.join(ids)})")
        L.append(f"- {q['id']} {q['question']} — {state}")
    return "\n".join(L) + "\n"


# ---------------------------------------------------------------- main

def build() -> dict[str, bytes]:
    ents = entities()
    ind_rows, cov, vals = indicators(ents)
    link_rows, link_notes = links(ents)
    qcov, qs = question_coverage(vals, len(ents))
    la_by: dict[str, list[dict[str, str]]] = {}
    for r in read_tsv(HERE / "leaving-america.tsv"):
        la_by.setdefault(r["iso2"], []).append(r)
    files: dict[str, bytes] = {
        "countries.tsv": tsv_bytes(ENTITY_COLS, ents),
        "indicators.tsv": tsv_bytes(["key", "indicator", "value", "year", "source", "manifest_id"], ind_rows),
        "indicator-coverage.tsv": tsv_bytes(["indicator", "label", "unit", "source", "manifest_id", "licence",
                                             "with_value", "total", "coverage", "years", "note"], cov),
        "links.tsv": tsv_bytes(LINK_COLS, link_rows),
        "question-coverage.tsv": tsv_bytes(["id", "question", "answered_by", "answer_kind",
                                            "entities_with_any", "total"], qcov),
    }
    links_by = {r["key"]: r for r in link_rows}
    index = []
    for e in ents:
        name = f"profiles/{e['key'].lower()}.md"
        files[name] = profile(e, vals, links_by[e["key"]], la_by.get(e.get("iso2", ""), []) if e.get("iso2") else [],
                              qs, link_notes).encode("utf-8")
        filled = sum(1 for iid, *_ in IND_DEFS if e["key"] in vals[iid])
        index.append({"key": e["key"], "name_en": e["name_en"], "profile": name,
                      "indicators_filled": f"{filled}/{len(IND_DEFS)}",
                      "leaving_america": "yes" if e.get("iso2") in la_by else "no"})
    files["profiles/index.tsv"] = tsv_bytes(["key", "name_en", "profile", "indicators_filled", "leaving_america"], index)
    return files


def main(argv: list[str]) -> int:
    files = build()
    if argv[:1] == ["check"]:
        bad = [n for n, b in files.items() if not (HERE / n).exists() or (HERE / n).read_bytes() != b]
        stale = sorted(p.name for p in (HERE / "profiles").glob("*.md") if f"profiles/{p.name}" not in files)
        for n in bad:
            print(f"DIFFERS {n}")
        for n in stale:
            print(f"STALE profiles/{n}")
        print(f"check: {len(files)} files, {len(bad) + len(stale)} problems")
        return 1 if bad or stale else 0
    (HERE / "profiles").mkdir(exist_ok=True)
    for p in (HERE / "profiles").glob("*.md"):
        if f"profiles/{p.name}" not in files:
            p.unlink()
    for n, b in sorted(files.items()):
        (HERE / n).write_bytes(b)
    digest = hashlib.sha256(b"".join(n.encode() + b"\0" + files[n] for n in sorted(files))).hexdigest()
    print(f"wrote {len(files)} files; tree sha256={digest}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

